api_examples:
Python streaming example:

async with client.stream_items(query=..., buffer_size=32) as stream:
    async for item in stream:
        process(item)

# To resume from cursor:
stream = client.stream_items(query=..., resume_from=stored_cursor)
TypeScript async iterator example:

const it = client.streamItems({ query, bufferSize: 32 });
for await (const item of it) {
  process(item);
}

// Cursor-based pagination helper
for await (const page of client.listPages({pageSize: 100})) {
  handle(page.items);
  if (page.nextCursor) persistCursor(page.nextCursor);
}
Go example (channel-based):

ctx, cancel := context.WithCancel(context.Background())
defer cancel()
ch, err := client.StreamItems(ctx, StreamOptions{Query: q, BufferSize: 16})
for item := range ch {
  process(item)
}
